153	// failWriter fails every write after a successful prefix of n bytes.
154	type failWriter struct {
155		n   int
156		err error
157	}
158	
159	func (w *failWriter) Write(p []byte) (int, error) {
160		if w.n >= len(p) {
161			w.n -= len(p)
162			return len(p), nil
163		}
164		return 0, w.err
165	}
