		"duplicate block field": `{"version":1,"tip":1,"blocks":[` +
			`{"height":1,"height":1,"hash":"h1","parent":"g","txs":[]}` +
			`]}`,
		"unknown top field": `{"version":1,"tip":0,"blocks":[],"extra":1}`,
