			`{"height":1,"hash":"","parent":"g","txs":[]}` +
			`]}`,
		"duplicate hash": `{"version":1,"tip":2,"blocks":[` +
			`{"height":1,"hash":"h1","parent":"g","txs":[]},` +
			`{"height":2,"hash":"h1","parent":"h1","txs":[]}` +
