81	func buildRestoreIngestChain(t *testing.T) *Index {
82		t.Helper()
83		index := New()
84		for _, b := range restoreIngestOldChainBlocks() {
85			if err := index.Append(b); err != nil {
86				t.Fatalf("setup append at height %d: %v", b.Height, err)
87			}
88		}
89		return index
90	}
