188		// Existing append rules are still enforced during the read window: a
189		// block not extending the current tip is rejected and changes nothing.
190		blocks, byHash, tip := snapshot(index)
191		if err := index.Append(Block{Height: 3, Hash: "r3", Parent: "h1", Txs: []string{"r"}}); err == nil {
192			t.Fatal("append with a non-tip parent must be rejected while the restore reads")
193		}
194		requireUnchanged(t, index, blocks, byHash, tip)
195	
196		// The legal append extends the OLD chain tip and returns before the
197		// restore ends.
198		if err := index.Append(restoreIngestAppendedBlock()); err != nil {
199			t.Fatalf("append while restore is reading: %v", err)
200		}
201		select {
202		case err := <-restoreDone:
203			t.Fatalf("restore returned while its input was still gated: %v", err)
204		default:
205		}
