76	// requireSameChainData fails unless got holds exactly want's main chain: tip,
77	// per-height block content under sameBlock semantics (an empty tx list equals
78	// a missing one, but a missing timestamp never equals zero), and the by-hash
79	// index.
80	func requireSameChainData(t *testing.T, got, want *Index) {
81		t.Helper()
82		if got.Tip != want.Tip {
83			t.Fatalf("tip=%d, want %d", got.Tip, want.Tip)
84		}
85		if len(got.Blocks) != len(want.Blocks) || len(got.ByHash) != len(want.ByHash) {
86			t.Fatalf("index sizes differ: got blocks=%d byHash=%d, want blocks=%d byHash=%d",
87				len(got.Blocks), len(got.ByHash), len(want.Blocks), len(want.ByHash))
88		}
89		for height := int64(1); height <= want.Tip; height++ {
90			if !sameBlock(got.Blocks[height], want.Blocks[height]) {
91				t.Fatalf("block at height %d differs:\ngot  %+v\nwant %+v", height, got.Blocks[height], want.Blocks[height])
92			}
93		}
94		if !reflect.DeepEqual(got.ByHash, want.ByHash) {
95			t.Fatalf("by-hash indexes differ:\ngot  %v\nwant %v", got.ByHash, want.ByHash)
96		}
97	}
