99	// requireSameTxAnswers fails unless a and b return the same ordered hits,
100	// totals, matched-block counts, pinned upper heights, and cursor endings for
101	// the query (followed through every page).
102	func requireSameTxAnswers(t *testing.T, a, b *Index, query TxQuery) {
103		t.Helper()
104		pagesA := collectPages(t, a, query)
105		pagesB := collectPages(t, b, query)
106		if len(pagesA) != len(pagesB) {
107			t.Fatalf("query %+v: %d pages vs %d", query, len(pagesA), len(pagesB))
108		}
109		for i := range pagesA {
110			pa, pb := pagesA[i], pagesB[i]
111			if !reflect.DeepEqual(pa.Hits, pb.Hits) ||
112				pa.TotalMatches != pb.TotalMatches ||
113				pa.MatchedBlocks != pb.MatchedBlocks ||
114				pa.ToHeight != pb.ToHeight ||
115				(pa.NextCursor == "") != (pb.NextCursor == "") {
116				t.Fatalf("query %+v page %d differs:\ngot  %+v\nwant %+v", query, i, pb, pa)
117			}
118		}
119	}
