121	// requireExactTxAnswer fails unless a first page for query carries exactly the
122	// given hits, total, and matched-block count. The fixture chains are short
123	// enough for one page to hold every hit.
124	func requireExactTxAnswer(t *testing.T, index *Index, query TxQuery, wantHits []TxHit, wantTotal, wantBlocks int64) {
125		t.Helper()
126		page, err := index.QueryTxs(query)
127		if err != nil {
128			t.Fatalf("query %+v failed: %v", query, err)
129		}
130		if !reflect.DeepEqual(page.Hits, wantHits) {
131			t.Fatalf("query %+v hits=%v, want %v", query, page.Hits, wantHits)
132		}
133		if page.TotalMatches != wantTotal || page.MatchedBlocks != wantBlocks {
134			t.Fatalf("query %+v total=%d blocks=%d, want total=%d blocks=%d",
135				query, page.TotalMatches, page.MatchedBlocks, wantTotal, wantBlocks)
136		}
137	}
