139	// The rewritten spelling must really differ from the canonical spelling in the
140	// ways this regression cares about; otherwise the fixture would prove nothing.
141	func TestTextualSnapshotFixturesAreGenuinelyDifferentSpellings(t *testing.T) {
142		if textRewrittenV1 == textCanonicalV1 {
143			t.Fatal("rewritten fixture must not be byte-identical to the canonical fixture")
144		}
145		for _, marker := range []string{esc("0041"), esc("0068"), esc("94fe")} {
146			if !strings.Contains(textRewrittenV1, marker) {
147				t.Fatalf("rewritten fixture must use the %s escape: %s", marker, textRewrittenV1)
148			}
149		}
150		if !strings.ContainsAny(textRewrittenV1, "\n\t") {
151			t.Fatal("rewritten fixture must carry layout whitespace")
152		}
153		blocksAt := strings.Index(textRewrittenV1, `"blocks"`)
154		versionAt := strings.Index(textRewrittenV1, `"version"`)
155		if blocksAt < 0 || versionAt < 0 || blocksAt > versionAt {
156			t.Fatal("rewritten fixture must place blocks before version")
157		}
158		for _, doc := range []string{textCanonicalV1, textRewrittenV1} {
159			tip, blocks, err := parseSnapshot(strings.NewReader(doc))
160			if err != nil {
161				t.Fatalf("fixture must parse: %v", err)
162			}
163			if tip != 3 || len(blocks) != 3 {
164				t.Fatalf("fixture parsed tip=%d blocks=%d, want 3/3", tip, len(blocks))
165			}
166		}
167	}
