169	// Both spellings of the same legal snapshot restore to the same chain and the
170	// same query answers as ingesting the blocks directly: heights, hashes, parent
171	// links, and transaction order are identical even though block 2's parent and
172	// block 3's parent arrived as Unicode escapes. Version-1 blocks restore with
173	// no timestamp at all.
174	func TestRestoreCanonicalAndRewrittenV1SnapshotYieldSameChain(t *testing.T) {
175		source := chain(t, textualV1Blocks()...)
176	
177		instances := map[string]*Index{"ingested": source}
178		for name, doc := range map[string]string{
179			"canonical layout": textCanonicalV1,
180			"rewritten layout": textRewrittenV1,
181		} {
182			index := New()
183			if err := index.Restore(strings.NewReader(doc)); err != nil {
184				t.Fatalf("%s restore failed: %v", name, err)
185			}
186			instances[name] = index
187		}
188	
189		for name, index := range instances {
190			t.Run(name, func(t *testing.T) {
191				requireSameChainData(t, index, source)
192				// Every block of a version-1 restore carries a missing time.
193				for height := int64(1); height <= 3; height++ {
194					if index.Blocks[height].Time != nil {
195						t.Fatalf("height %d time=%v, want missing after v1 restore", height, index.Blocks[height].Time)
196					}
197				}
198				// The escaped parent links decoded to the same hashes.
199				if index.Blocks[2].Hash != "链" || index.Blocks[2].Parent != "h1" ||
200					index.Blocks[3].Parent != "链" {
201					t.Fatalf("escaped identifiers changed block linkage: %+v %+v", index.Blocks[2], index.Blocks[3])
202				}
203			})
204		}
205	
206		// Queries use the decoded identifier: "Ab" matches both the literal
207		// "Ab" entries and the ones written "Ab", keeping every occurrence,
208		// its in-block position, and the matched-block count.
209		abHits := []TxHit{
210			{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 0},
211			{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 2},
212			{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 7},
213			{Height: 2, BlockHash: "链", TxID: "Ab", Position: 1},
214			{Height: 2, BlockHash: "链", TxID: "Ab", Position: 2},
215			{Height: 3, BlockHash: "h3", TxID: "Ab", Position: 1},
216		}
217		emptyHits := []TxHit{
218			{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
219			{Height: 2, BlockHash: "链", TxID: "", Position: 0},
220		}
221		allHits := []TxHit{
222			{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 0},
223			{Height: 1, BlockHash: "h1", TxID: "x", Position: 1},
224			{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 2},
225			{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
226			{Height: 1, BlockHash: "h1", TxID: "Ab ", Position: 4},
227			{Height: 1, BlockHash: "h1", TxID: "ab", Position: 5},
228			{Height: 1, BlockHash: "h1", TxID: "A b", Position: 6},
229			{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 7},
230			{Height: 2, BlockHash: "链", TxID: "", Position: 0},
231			{Height: 2, BlockHash: "链", TxID: "Ab", Position: 1},
232			{Height: 2, BlockHash: "链", TxID: "Ab", Position: 2},
233			{Height: 3, BlockHash: "h3", TxID: "ab", Position: 0},
234			{Height: 3, BlockHash: "h3", TxID: "Ab", Position: 1},
235		}
236		for _, name := range []string{"canonical layout", "rewritten layout"} {
237			index := instances[name]
238			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{"Ab"}}, abHits, 6, 3)
239			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{""}}, emptyHits, 2, 2)
240			requireExactTxAnswer(t, index, TxQuery{}, allHits, 13, 3)
241			// Case and interior/trailing whitespace are part of the identifier:
242			// textual tolerance must not merge the distinct spellings.
243			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{"ab"}}, []TxHit{
244				{Height: 3, BlockHash: "h3", TxID: "ab", Position: 0},
245			}, 1, 1)
246			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{"Ab "}}, []TxHit{
247				{Height: 1, BlockHash: "h1", TxID: "Ab ", Position: 4},
248			}, 1, 1)
249			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{"A b"}}, []TxHit{
250				{Height: 1, BlockHash: "h1", TxID: "A b", Position: 6},
251			}, 1, 1)
252			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{"AB"}}, []TxHit{}, 0, 0)
253			// A filtered query likewise sees the decoded, order-preserving data.
254			requireExactTxAnswer(t, index, TxQuery{TxIDs: []string{"Ab", "ab"}}, []TxHit{
255				{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 0},
256				{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 2},
257				{Height: 1, BlockHash: "h1", TxID: "Ab", Position: 7},
258				{Height: 2, BlockHash: "链", TxID: "Ab", Position: 1},
259				{Height: 2, BlockHash: "链", TxID: "Ab", Position: 2},
260				{Height: 3, BlockHash: "h3", TxID: "ab", Position: 0},
261				{Height: 3, BlockHash: "h3", TxID: "Ab", Position: 1},
262			}, 7, 3)
263			// The rewritten spelling gives exactly the query behavior of the
264			// canonical spelling and of direct ingestion.
265			requireSameTxAnswers(t, index, source, TxQuery{})
