502			t.Run(tc.name, func(t *testing.T) {
503				index := txChain(t, []string{"a"}, []string{"b"})
504				blocks, byHash, tip := snapshot(index)
505				before := exportString(t, index)
506	
507				err := index.Restore(strings.NewReader(tc.input))
508				if !errors.Is(err, ErrInvalidSnapshot) {
509					t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
510				}
511				if err == ErrInvalidSnapshot || !strings.Contains(err.Error(), tc.reason) {
512					t.Fatalf("err=%v, want a specific reason containing %q", err, tc.reason)
513				}
514	
515				// The preexisting main chain is unchanged and still queryable.
516				requireUnchanged(t, index, blocks, byHash, tip)
517				if after := exportString(t, index); after != before {
518					t.Fatalf("export changed after rejected restore:\n%s\n%s", before, after)
519				}
520				page, err := index.QueryTxs(TxQuery{TxIDs: []string{"a"}})
521				if err != nil || page.TotalMatches != 1 {
522					t.Fatalf("old chain query after rejection: page=%+v err=%v", page, err)
523				}
524	
525				// Nothing from the rejected document was applied: not even the
526				// valid prefix before the defect.
527				for _, hash := range tc.newHashes {
528					if _, ok := index.ByHash[hash]; ok {
529						t.Fatalf("rejected input left hash %q indexed: %v", hash, index.ByHash)
530					}
531				}
532				if leaked, err := index.QueryTxs(TxQuery{TxIDs: []string{"p"}}); err != nil || leaked.TotalMatches != 0 {
533					t.Fatalf("rejected input left its prefix transactions: page=%+v err=%v", leaked, err)
534				}
535			})
536		}
537	}
538

